:root {
  /* Colors */
  --color-cobalt-signal: #2545ff;
  --color-paper-canvas: #ffffff;
  --color-fog-panel: #fafafa;
  --color-linen-reverse: #f9f8f6;
  --color-concrete-tile: #f3f3f3;
  --color-frosted-banner: #c8d0ff;
  --color-onyx-ink: #171417;
  --color-graphite-nav: #222222;
  --color-pewter-caption: #484747;
  --color-quartz-border: #e6e6e4;
  --color-mist-rule: #dbdfec;
  --color-indigo-vault: #0c1754;

  /* Typography — Font Families */
  --font-abcfavoritvariable: "Abcfavoritvariable", "Hanken Grotesk", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter-hosted: "Inter hosted", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-martinaplantijn: "Martinaplantijn", "Crimson Pro", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;

  /* Typography — Scale */
  --text-small: 13.5px;
  --leading-small: 1.4;
  --tracking-small: 0px;
  --text-caption: 14px;
  --leading-caption: 1.4;
  --tracking-caption: 0px;
  --text-body-sm: 16px;
  --leading-body-sm: 1.6;
  --tracking-body-sm: 0px;
  --text-body: 18px;
  --leading-body: 1.4;
  --tracking-body: 0px;
  --text-subheading: 27px;
  --leading-subheading: 1.1;
  --tracking-subheading: -0.54px;
  --text-heading-sm: 36px;
  --leading-heading-sm: 1.1;
  --tracking-heading-sm: -0.72px;
  --text-heading: 45px;
  --leading-heading: 1.1;
  --tracking-heading: -0.9px;
  --text-heading-lg: 54px;
  --leading-heading-lg: 1.1;
  --tracking-heading-lg: -1.08px;
  --text-display: 72px;
  --leading-display: 1;
  --tracking-display: -3.6px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-9: 9px;
  --spacing-13: 13px;
  --spacing-16: 16px;
  --spacing-18: 18px;
  --spacing-20: 20px;
  --spacing-27: 27px;
  --spacing-36: 36px;
  --spacing-45: 45px;
  --spacing-54: 54px;
  --spacing-72: 72px;
  --spacing-90: 90px;
  --spacing-108: 108px;
  --spacing-144: 144px;

  /* Layout */
  --layout-max-width: 1440px;
  --layout-section-gap: 90px;
  --layout-card-padding: 20px;
  --layout-element-gap: 18px;

  /* Border Radius */
  --radius-sm: 2.25px;
  --radius-md: 18px;
  --radius-lg: 24px;
  --radius-xl: 27px;
  --radius-2xl: 40px;
  --radius-full: 100px;

  /* Named Radii */
  --radius-buttons: 100px;
  --radius-pills: 100px;
  --radius-cards: 24px;
  --radius-images: 27px;
  --radius-innerTiles: 18px;
  --radius-sections: 40px;
  --radius-avatars: 50%;
  --radius-inputs: 0px;
  --radius-smallElements: 2.25px;

  /* Shadows */
  --shadow-subtle: rgba(37, 69, 255, 0.1) 0px 4px 8px 0px;
  --shadow-sm: rgba(0, 0, 0, 0.04) 0px 1px 2px 0px, rgba(0, 0, 0, 0.08) 0px 8px 24px 0px;
  --shadow-md: rgba(0, 0, 0, 0.1) 0px 4px 16px 0px;
  --shadow-md-2: rgba(0, 0, 0, 0.15) 0px 2px 15px 0px;
  --shadow-lg: rgba(37, 69, 255, 0.1) 0px 4.318px 8.635px 0px, rgba(37, 58, 177, 0.05) 0px 12.953px 25.906px 0px, rgba(37, 58, 177, 0.05) 0px 34.541px 43.176px 0px;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-fog-panel: #fafafa;
  --surface-concrete-tile: #f3f3f3;
  --surface-indigo-vault: #0c1754;
}

